// sotc: GPU-written allocation sites (SOTC_GPU_PLACE=1). A site is the key the alloc registry uses
// (caller1, caller2, caller3, heap slot). The built-in table (gpu_sites_default.inc, generated by
// tools/gen_gpu_sites.py from user/alloc_sites.tsv) lists the sites the GPU writes; sites learned at run time
// (SOTC_ALLOC_SITES=1, alloc_sites.cpp) are added to the table and saved to user/gpu_sites.bin.
//
// Lookup is lock-free: the table is a fixed-size open-addressing array with insert-only semantics. A slot is
// empty, being filled, or ready; its identity and flags are written before it is published, so readers that see
// it ready read immutable fields.
#pragma once

#include <cstdint>
#include <string>

namespace SotcGpuSites {

/// Flag bit 0: the site is a per-frame ring heap (RenderSingleFrame GPU/CPU rings, slots 15 and 17).
constexpr uint32_t kFlagRing = 1u;

/// True when SOTC_GPU_PLACE=1 (read once). Lookup and Learn do not check it; the caller decides.
bool On();

/// Ring heap slots (the set the generator and the learning hook use for kFlagRing).
bool IsRingSlot(uint32_t slot);
/// The flags a learned site of this heap slot gets (kFlagRing for ring slots, 0 otherwise).
uint32_t SlotFlags(uint32_t slot);

/// Builds the table from the built-in rows and user/gpu_sites.bin (if present and valid). Idempotent and thread-safe.
/// Lookup and Learn load the table on first use, so calling Load() is optional.
void Load();

/// True when the site is in the table; flags receives its flags (may be null). Lock-free, safe from any thread.
bool Lookup(uint64_t c1, uint64_t c2, uint64_t c3, uint32_t slot, uint32_t* flags);

/// Inserts a learned site (insert-only, thread-safe). A site already in the table is left unchanged. Marks the
/// table dirty when it inserts.
void Learn(uint64_t c1, uint64_t c2, uint64_t c3, uint32_t slot, uint32_t flags);

/// Writes user/gpu_sites.bin (format "SGS1", u32 count, then count records {u64 c1, c2, c3; u32 slot, flags}, all
/// little-endian) with every entry in the table. Does nothing when the table is clean.
void Save();

/// Save() when the table is dirty and at least 30 s passed since the last save.
void MaybeSave();

/// Appends one summary line (entries, built-in, learned, lookups, hits, overflow) to out.
void Report(std::string& out);

} // namespace SotcGpuSites
